import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"repair-station-business/index.md","filePath":"repair-station-business/index.md"}'),n={name:"repair-station-business/index.md"};function o(r,e,l,p,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>The paid add-on of <a href="/repair-station/">Repair Station</a>: players buy repair stations, stock them with parts, set their prices and collect the till. Everything is managed from a tablet at the station, and every setting is edited in game.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Stations for sale</strong>: you pick which Repair Stations can be bought and at what price. See <a href="/repair-station-business/ownership">Ownership</a>.</li><li><strong>Owner tablet</strong>: stock, till, last operations, prices, name and sale of the station, in one place.</li><li><strong>Parts</strong>: every repair uses parts from the stock of the station, bought with the bank account or handed in as items. See <a href="/repair-station-business/stock">Stock</a>.</li><li><strong>Owner prices</strong>: each owner sets a percentage of the base price, within the limits you choose, and a tax is kept on every payment.</li><li><strong>Fair endings</strong>: an owner who sells, is evicted or goes inactive is paid back part of the purchase price plus the till, even when offline.</li><li><strong>Admin panel</strong>: put stations on sale, change their price, set the stock of owned stations or evict an owner, without leaving the game.</li><li><strong>HTTP API and webhooks</strong>: stations, ledger and statistics for your website, and a Discord message for every purchase, restock, withdrawal and loss of station. See <a href="/repair-station-business/api">API and webhooks</a>.</li><li><strong>Six languages</strong>: English, French, Spanish, Portuguese, Polish, German.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detected automatically.</li><li>Dependencies: oxmysql, <code>nay_lib</code> and <a href="/repair-station/">Repair Station</a> (<code>nay_repair</code>), included with your purchase of the scripts.</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Full steps on the <a href="/getting-started">Getting started</a> page. Then give yourself <code>nay_repair_business.config</code> (or <code>nay.admin</code>) and open <code>/nay</code>, or type <code>/nay:repairbusiness</code> for the admin panel. Mark the stations you want to sell in the panel: until then, stations behave like plain Repair Stations.</p>`,9)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
